  DWORD exit_code;
  GetExitCodeProcess(pi.hProcess, &exit_code);
  CloseHandle(pi.hProcess);
  CloseHandle(pi.hThread);

  if (!should_crash) {
    ASSERT_EQ(exit_code, 0) << "Process failed with exit code: " << exit_code;
  }

#else
