    waitpid(pid, &status, 0);
  } else {
    waitpid(pid, &status, 0);
    ASSERT_TRUE(WIFEXITED(status))
        << "Child process did not exit normally. Terminated by signal?";
    int exit_code = WEXITSTATUS(status);
    ASSERT_EQ(exit_code, 0) << "optimizer failed with exit code: " << exit_code;
  }
#endif
}


